def movesToStamp(stamp: str, target: str):
    # Convert target to list for mutability
    target = list(target)
    m, n = len(stamp), len(target)
    res = []
    changed = True
    visited = [False] * (n - m + 1)
    stars = 0  # How many ? already in target

    # Helper: can we stamp at pos?
    def can_stamp(pos):
        replaced = False
        for i in range(m):
            if target[pos + i] != '?' and target[pos + i] != stamp[i]:
                return False
            if target[pos + i] != '?':
                replaced = True  # At least one char would be actually replaced
        return replaced

    while stars < n:
        progress = False
        # Try every window
        for i in range(n - m + 1):
            if not visited[i] and can_stamp(i):
                # Stamp: set chars to '?'
                for j in range(m):
                    if target[i + j] != '?':
                        target[i + j] = '?'
                        stars += 1
                visited[i] = True
                progress = True
                res.append(i)
        if not progress:
            return []
    # Reverse to get actual stamping order
    return res[::-1]
